-- Real product copy.
--
-- The seed wrote one description per CATEGORY and reused it, so 24 products
-- shared 8 descriptions and 8 care notes; subtitle just repeated the category
-- name already shown above it; and seo_title / seo_description were null on
-- every product, so each page shipped without a meta description.
--
-- Titles stay in English. The reference storefront names its products in
-- English too, and these are imported goods whose names customers search for
-- as-is -- translating them would make the catalogue harder to search, not
-- easier to read. The Mongolian now lives in subtitle and description, where
-- it actually describes the thing. Two titles were malformed at import and are
-- corrected here.

with copy (slug, title, subtitle, description, care_details) as (values
  ('star-hairclip', null, 'Одон хэлбэрт үсний хавчаар', 'Одны хэлбэртэй, тод өнгийн хавчаар. Хөнгөн боловч бариул нь нягт учир нарийн үсийг ч сайн тогтооно.', 'Усанд норгохоос сэргийлнэ. Зөөлөн даавуугаар арчина.'),
  ('metal-floral-hair-clip', null, 'Цэцэг хээт металл хавчаар', 'Нарийн цэцэг хээгээр чимэглэсэн металл хавчаар. Өдөр тутам болон баярын хувцастай адилхан зохицно.', 'Үнэртэй ус, шингэн бодисоос хол байлгана. Хуурай газар хадгална.'),
  ('lucky-coin-phone-chain', null, 'Азын зоостой утасны гинж', 'Гараар сүлжсэн олс, азын зоос, жижиг сахиус бүхий гинж. Утсаа мөрөндөө үүрэх боломжтой.', 'Олсыг хэт чангаар татахаас зайлсхийнэ. Норсон бол сүүдэрт хатаана.'),
  ('small-woven-pilow-laptop-bag', null, 'Нэхмэл гадаргуутай компьютерийн цүнх', 'Зузаан нэхмэл гадаргуутай, дотроо зөөлөн доторлогоотой цүнх. 13 инчийн зөөврийн компьютер багтана.', 'Гараар угаана. Хэлбэрээ хадгалахын тулд шулуун тавьж хатаана.'),
  ('ok-laptop-bag', null, 'Ромбо хээт компьютерийн цүнх', 'Ромбо хээгээр хатгасан зөөлөн цүнх. Урт бариулыг нь мөрөвч болгон тохируулж хэрэглэнэ.', '30°C-аас доош температурт гараар угаана. Цайруулагч хэрэглэхгүй.'),
  ('denim-patchwork-laptop-bag', 'Denim Patchwork Laptop Bag', 'Денимээр эсгэсэн компьютерийн цүнх', 'Өөр өөр өнгийн денимийн хэсгүүдийг холбон оёсон цүнх. Ширхэг бүр өөрийн гэсэн хээтэй.', 'Тусад нь угаана — деним анхны угаалтад өнгө гаргах магадлалтай.'),
  ('vintage-patchwork-baseball-cap', null, 'Ретро эсгэмэл бейсболын малгай', 'Хуучирсан өнгө төрхтэй, хэсгүүдээр эсгэсэн малгай. Ар талын горойгоор хэмжээг тохируулна.', 'Гараар угаана. Хэлбэрээ хадгалахын тулд шахаж хураахгүй.'),
  ('tritan-sports-portable-bottle', null, 'Tritan спорт сав', 'Хөнгөн бөгөөд цохилтод тэсвэртэй Tritan материалтай. Бариултай тагтай учир аялалд тохиромжтой.', 'Бүлээн усаар угаана. Угаалгын машинд хийхгүй.'),
  ('love-patchwork-baseball-cap', null, 'Зүрх хээт бейсболын малгай', 'Урд талдаа зүрхэн хээгээр эсгэсэн хөвөн малгай. Өдөр тутмын хувцастай хялбар зохицно.', 'Гараар угаана. Шууд нарны гэрэлд удаан хатаахгүй.'),
  ('dress-up-game-knit-gloves', null, 'Сүлжмэл дулаан бээлий', 'Зузаан сүлжмэлээр хийсэн дулаан бээлий. Хуруу нь уян тул гар утас хэрэглэхэд саад болохгүй.', 'Гараар угаана. Мушгиж шахахгүй, шулуун тавьж хатаана.'),
  ('soft-home-slippers', null, 'Гэрийн зөөлөн шаахай', 'Зузаан хөвөн улавчтай гэрийн шаахай. Алхахад чимээгүй бөгөөд дулаан.', 'Гараар угаана. Дулаан агаарт хатаана.'),
  ('wonderful-backyard-colorful-woven-cap', null, 'Өнгөлөг нэхмэл малгай', 'Гараар сүлжсэн өнгөлөг малгай. Хавар, намрын сэрүүн өдрүүдэд тохиромжтой.', 'Зөөлөн угаалгын нунтгаар гараар угаана.'),
  ('flower-vacuum-bottle', null, 'Цэцэг хээт термос сав', 'Хоёр давхар ханатай тул халуун болон хүйтнээ удаан хадгална. Зөөхөд эвтэйхэн бариултай таг.', 'Гараар угаана. Буцалж байгаа ус шууд хийхгүй.'),
  ('portable-vacuum-bottle', null, 'Зөөврийн нимгэн термос', 'Цүнхэнд амархан багтах нимгэн хэлбэртэй. Нэг гараар онгойлгох тагтай.', 'Гараар угаана. Угаалгын машинд хийхгүй.'),
  ('apple-sippy-cup', null, 'Алим хэлбэртэй сорох аяга', 'Алим хэлбэртэй, сорогчтой аяга. Асгарахаас хамгаалсан нягт таг.', 'Бүлээн усаар угаана. Сорогчийг салгаж тусад нь угаана.'),
  ('little-tail-phone-case', null, 'Сүүлэн чимэглэлтэй утасны гэр', 'Жижиг сүүлэн чимэглэлтэй зөөлөн гэр. Булангуудыг өргөтгөж цохилтоос хамгаална.', 'Чийгтэй даавуугаар арчина.'),
  ('make-you-happy-phone-case-with-metal-heart-bracket', null, 'Зүрхэн тулгууртай утасны гэр', 'Ар талдаа металл зүрхэн тулгууртай гэр. Утсаа ширээн дээр тавьж үзэхэд тохиромжтой.', 'Тулгуурыг хэт нугалахаас зайлсхийнэ.'),
  ('get-rich-magnetic-phone-case', null, 'Соронзон утасны гэр', 'MagSafe соронзонтой нийцтэй гэр. Гэрийг нь салгалгүйгээр утасгүй цэнэглэнэ.', 'Чийгтэй даавуугаар арчина. Уусгагч бодис хэрэглэхгүй.'),
  ('call-me-texure-gem-hair-grab', null, 'Чулуун чимэглэлтэй үсний хавчаар', 'Товойсон гадаргуу дээр гялалзсан чулуу суулгасан том хавчаар. Зузаан үсийг ч бариад тогтооно.', 'Усанд норгохоос сэргийлнэ. Зөөлөн даавуугаар арчина.'),
  ('hair-claw', null, 'Үсний хумс хавчаар', 'Энгийн хэлбэрийн том хумс хавчаар. Өдөр тутам үс хураахад хамгийн их хэрэглэгддэг зүйл.', 'Хуурай газар хадгална. Хүчтэй мушгихаас зайлсхийнэ.'),
  ('cream-bulging-love-hairclip', null, 'Зүрхэн хэлбэрт үсний хавчаар', 'Товгор зүрхэн хэлбэртэй, зөөлөн өнгийн хавчаар. Нарийн болон дунд зэргийн үсэнд тохиромжтой.', 'Усанд норгохоос сэргийлнэ. Зөөлөн даавуугаар арчина.'),
  ('pet-toys', null, 'Тэжээвэр амьтны зөөлөн тоглоом', 'Дотроо чимээ гаргагчтай зөөлөн тоглоом. Нохой, муур хоёрын аль алинд тохиромжтой.', 'Гараар угаана. Урагдаж эхэлсэн бол солино.'),
  ('lint-rollerr', 'Lint Roller', 'Ноос цэвэрлэгч роллер', 'Хувцас, тавилга дээрх үс, ноосыг хормын дотор цэвэрлэнэ. Сэлбэг роллыг тусад нь авна.', 'Наалдац нь буурсан үед хуудсыг нь урж хаяна.'),
  ('pet-raglan-stripe-t-shirt', null, 'Тэжээвэр амьтны судалтай цамц', 'Реглан ханцуйтай, судалтай хөвөн цамц. Хүзүү, цээжний хэсэг нь чөлөөтэй.', '30°C-аас доош температурт угаана. Хатаагч ашиглахгүй.')
)
update public.product_translations t
   set title       = coalesce(c.title, t.title),
       subtitle    = c.subtitle,
       description = c.description,
       care_details = c.care_details,
       -- Keep the brand out of seo_title's head: the product name is what a
       -- search result needs to lead with.
       seo_title       = coalesce(c.title, t.title) || ' — hotaru',
       seo_description = c.description
  from copy c
  join public.products p on p.slug = c.slug
 where t.product_id = p.id
   and t.locale = 'mn';
